"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useSyncExternalStore,
  type FocusEvent,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";
import { useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { BJORK_PALETTE, type BjorkTone } from "../_core/palette";
import { useBjorkTone } from "../_core/tone";
import { useVisibleLoop } from "../_core/loop";
import { mulberry32 } from "../_core/random";
import { stepSpring, type SpringConfig, type SpringState } from "../_core/spring";

export type MagneticMode = "attract" | "repel";

export interface MagneticLettersProps {
  text?: string;
  /** Letters lean toward the cursor, or shy away from it. */
  mode?: MagneticMode;
  /** Scales how far letters travel. 1 is the tuned default. */
  strength?: number;
  /** Reach of the field as a gaussian sigma, in em. */
  radius?: number;
  /** Spring stiffness for the snap back. */
  stiffness?: number;
  /** Spring damping. Lower overshoots more. */
  damping?: number;
  /** Click (or Enter / Space) scatters the letters and lets them reassemble. */
  shockwave?: boolean;
  tone?: BjorkTone;
  color?: string;
  /** Tint for letters deep in the field, and the shockwave ring. */
  accentColor?: string;
  /** Upper bound in px. The type also shrinks to fit its container. */
  fontSize?: number;
  fontFamily?: string;
  fontWeight?: number;
  /** Letter spacing in em. */
  tracking?: number;
  align?: "left" | "center";
  /**
   * Fixed pointer position as fractions of the box (0..1). Renders a still, displaced frame
   * with no loop — for previews and screenshots.
   */
  pointer?: { x: number; y: number };
  className?: string;
  ariaLabel?: string;
}

interface Glyph {
  cx: number;
  cy: number;
  x: SpringState;
  y: SpringState;
  r: SpringState;
  s: SpringState;
  /** Writes are skipped when nothing visible changed. */
  key: string;
  tint: number;
  kickAt: number;
  seed: number;
}

interface Ring {
  x: number;
  y: number;
  age: number;
}

const RING_LIFE = 0.9;
const subscribeNoop = () => () => {};
const clampAbs = (v: number, m: number) => (v > m ? m : v < -m ? -m : v);

interface FieldParams {
  mode: MagneticMode;
  strength: number;
  radius: number;
}

/** Field targets for one glyph given the pointer. Also sets the glyph's tint. */
function fieldTarget(g: Glyph, px: number, py: number, presence: number, L: FieldParams, em: number) {
  const sigma = Math.max(8, L.radius * em);
  const dx = px - g.cx;
  const dy = py - g.cy;
  const dist = Math.hypot(dx, dy) || 1;
  const f = Math.exp((-0.5 * dist * dist) / (sigma * sigma)) * presence;
  let tx: number;
  let ty: number;
  if (L.mode === "attract") {
    // Lean toward the cursor, never past it. Sideways pull is kept well under half a letter so
    // neighbours converging on the same point never collide; the lift carries the gesture.
    const pull = L.strength * f;
    tx = clampAbs(dx * pull * 0.11, em * 0.14 * L.strength);
    ty = clampAbs(dy * pull * 0.34, em * 0.42 * L.strength);
  } else {
    const push = em * 0.62 * L.strength * f;
    tx = (-dx / dist) * push;
    ty = (-dy / dist) * push;
  }
  // Lean into the direction of travel.
  const tr = clampAbs(tx * (60 / em), 14);
  const ts = L.mode === "attract" ? 1 + 0.07 * f * L.strength : 1 - 0.18 * f * L.strength;
  g.tint = L.mode === "attract" ? Math.round(Math.max(0, f - 0.45) * 70) : Math.round(Math.max(0, f - 0.5) * 60);
  return { tx, ty, tr, ts };
}

export function MagneticLetters({
  text = "Pull me closer",
  mode = "attract",
  strength = 1,
  radius = 1.35,
  stiffness = 210,
  damping = 15,
  shockwave = true,
  tone,
  color,
  accentColor,
  fontSize = 112,
  fontFamily = "var(--font-geist-sans), ui-sans-serif, system-ui, sans-serif",
  fontWeight = 640,
  tracking = -0.045,
  align = "center",
  pointer: fixedPointer,
  className,
  ariaLabel,
}: MagneticLettersProps) {
  const resolvedTone = useBjorkTone(tone);
  const palette = BJORK_PALETTE[resolvedTone];
  const ink = color ?? palette.text;
  const accent = accentColor ?? palette.accent;
  const reduced = useReducedMotion() ?? false;
  // Reduced motion is only known on the client; hold the first client render to the server's.
  const mounted = useSyncExternalStore(subscribeNoop, () => true, () => false);
  const still = (mounted && reduced) || fixedPointer !== undefined;
  const fixedX = fixedPointer?.x;
  const fixedY = fixedPointer?.y;

  const words = useMemo(() => text.split(/(\s+)/).filter((w) => w.length > 0), [text]);
  const longest = useMemo(() => words.reduce((m, w) => Math.max(m, Array.from(w).length), 1), [words]);

  const rootRef = useRef<HTMLDivElement>(null);
  const boxRef = useRef<HTMLDivElement>(null);
  const ringRef = useRef<SVGSVGElement>(null);
  const letters = useRef<HTMLSpanElement[]>([]);
  const field = useRef<Glyph[]>([]);
  const ptr = useRef({ x: 0, y: 0, active: false, presence: 0, touch: false });
  const ring = useRef<Ring | null>(null);
  const clock = useRef(0);
  const fontPx = useRef(fontSize);

  const live = useRef({ mode, strength, radius, stiffness, damping, ink, accent });
  useEffect(() => {
    live.current = { mode, strength, radius, stiffness, damping, ink, accent };
  }, [mode, strength, radius, stiffness, damping, ink, accent]);

  const collect = useCallback(() => {
    const box = boxRef.current;
    if (!box) return;
    const els = Array.from(box.querySelectorAll<HTMLSpanElement>("[data-letter]"));
    letters.current = els;
    fontPx.current = parseFloat(getComputedStyle(box).fontSize) || fontSize;
    const prev = field.current;
    field.current = els.map((el, i) => {
      // offsetLeft/Top ignore transforms, so these are the true rest positions.
      const cx = el.offsetLeft + el.offsetWidth / 2;
      const cy = el.offsetTop + el.offsetHeight / 2;
      const p = prev[i];
      if (p) return { ...p, cx, cy };
      return {
        cx,
        cy,
        x: { x: 0, v: 0 },
        y: { x: 0, v: 0 },
        r: { x: 0, v: 0 },
        s: { x: 1, v: 0 },
        key: "",
        tint: -1,
        kickAt: -1,
        seed: i,
      };
    });
  }, [fontSize]);

  const write = useCallback(() => {
    const { ink: c, accent: a } = live.current;
    const gs = field.current;
    for (let i = 0; i < gs.length; i++) {
      const g = gs[i];
      const el = letters.current[i];
      if (!el) continue;
      const key = `${g.x.x.toFixed(1)},${g.y.x.toFixed(1)},${g.r.x.toFixed(1)},${g.s.x.toFixed(3)}`;
      if (key !== g.key) {
        el.style.transform = `translate3d(${g.x.x.toFixed(2)}px, ${g.y.x.toFixed(2)}px, 0) rotate(${g.r.x.toFixed(2)}deg) scale(${g.s.x.toFixed(3)})`;
        g.key = key;
      }
      const tint = g.tint;
      const prevTint = Number(el.dataset.tint ?? -1);
      if (tint !== prevTint) {
        el.style.color = tint > 0 ? `color-mix(in oklab, ${a} ${tint}%, ${c})` : c;
        el.dataset.tint = String(tint);
      }
    }
    const svg = ringRef.current;
    const r = ring.current;
    if (svg) {
      if (r && r.age < RING_LIFE) {
        const k = r.age / RING_LIFE;
        const ease = 1 - (1 - k) ** 3;
        const size = fontPx.current * (0.4 + 5.5 * ease);
        svg.style.opacity = String((1 - k) * 0.7);
        svg.style.transform = `translate3d(${(r.x - 50).toFixed(1)}px, ${(r.y - 50).toFixed(1)}px, 0) scale(${(size / 100).toFixed(3)})`;
      } else if (svg.style.opacity !== "0") {
        svg.style.opacity = "0";
      }
    }
  }, []);

  const snapTo = useCallback(
    (fx: number, fy: number) => {
      const box = boxRef.current;
      if (!box) return;
      const px = fx * box.offsetWidth;
      const py = fy * box.offsetHeight;
      for (let gi = 0, gs = field.current; gi < gs.length; gi++) {
        const g = gs[gi];
        const { tx, ty, tr, ts } = fieldTarget(g, px, py, 1, live.current, fontPx.current);
        g.x = { x: tx, v: 0 };
        g.y = { x: ty, v: 0 };
        g.r = { x: tr, v: 0 };
        g.s = { x: ts, v: 0 };
      }
      write();
    },
    [write],
  );

  const frame = useCallback(
    (dt: number) => {
      clock.current += dt;
      const L = live.current;
      const p = ptr.current;
      p.presence += ((p.active ? 1 : 0) - p.presence) * (1 - Math.exp(-dt * (p.active ? 10 : 4)));
      const cfg: SpringConfig = { stiffness: L.stiffness, damping: L.damping, mass: 1 };
      const rcfg: SpringConfig = { stiffness: L.stiffness * 0.8, damping: L.damping * 0.85, mass: 1 };
      let moving = false;
      for (let gi = 0, gs = field.current; gi < gs.length; gi++) {
        const g = gs[gi];
        if (g.kickAt >= 0 && clock.current >= g.kickAt) {
          // Focus ripple: a small hop with a lean.
          g.y.v -= fontPx.current * 2.2;
          g.r.v += (g.seed % 2 ? 1 : -1) * 60;
          g.s.v += 1.2;
          g.kickAt = -1;
        }
        const { tx, ty, tr, ts } = fieldTarget(g, p.x, p.y, p.presence, L, fontPx.current);
        stepSpring(g.x, tx, cfg, dt);
        stepSpring(g.y, ty, cfg, dt);
        stepSpring(g.r, tr, rcfg, dt);
        stepSpring(g.s, ts, cfg, dt);
        if (
          g.kickAt >= 0 ||
          Math.abs(g.x.x - tx) + Math.abs(g.y.x - ty) > 0.05 ||
          Math.abs(g.r.x - tr) > 0.05 ||
          Math.abs(g.s.x - ts) > 0.0005 ||
          Math.abs(g.x.v) + Math.abs(g.y.v) + Math.abs(g.r.v) > 0.05
        )
          moving = true;
      }
      if (ring.current) {
        ring.current.age += dt;
        if (ring.current.age >= RING_LIFE) ring.current = null;
        else moving = true;
      }
      write();
      if (!moving && !p.active && p.presence < 0.002) return false;
    },
    [write],
  );

  const { wake } = useVisibleLoop(rootRef, frame, { enabled: !still });

  useLayoutEffect(() => {
    const box = boxRef.current;
    if (!box) return;
    let cancelled = false;
    const refresh = () => {
      collect();
      if (fixedX !== undefined && fixedY !== undefined) snapTo(fixedX, fixedY);
      else write();
    };
    refresh();
    const ro = new ResizeObserver(refresh);
    ro.observe(box);
    document.fonts?.ready.then(() => {
      if (!cancelled) refresh();
    });
    return () => {
      cancelled = true;
      ro.disconnect();
    };
  }, [collect, snapTo, write, fixedX, fixedY, text, fontSize, fontWeight, fontFamily, tracking]);

  useEffect(() => {
    if (still) return;
    const box = boxRef.current;
    if (!box) return;
    const local = (clientX: number, clientY: number) => {
      const rect = box.getBoundingClientRect();
      const scale = box.offsetWidth > 0 ? rect.width / box.offsetWidth : 1;
      return { x: (clientX - rect.left) / scale, y: (clientY - rect.top) / scale, rect, scale };
    };
    const onMove = (e: PointerEvent) => {
      const p = ptr.current;
      if (e.pointerType === "touch" && !p.touch) return;
      const { x, y, rect, scale } = local(e.clientX, e.clientY);
      const pad = fontPx.current * live.current.radius * 2 * scale;
      const near =
        e.clientX > rect.left - pad && e.clientX < rect.right + pad && e.clientY > rect.top - pad && e.clientY < rect.bottom + pad;
      p.x = x;
      p.y = y;
      p.active = near;
      if (near) wake();
    };
    const release = (e?: PointerEvent) => {
      if (e && e.pointerType !== "touch") return;
      ptr.current.touch = false;
      ptr.current.active = false;
      wake();
    };
    const onLeave = () => {
      ptr.current.active = false;
      wake();
    };
    window.addEventListener("pointermove", onMove, { passive: true });
    window.addEventListener("pointerup", release, { passive: true });
    window.addEventListener("pointercancel", release, { passive: true });
    document.documentElement.addEventListener("pointerleave", onLeave);
    window.addEventListener("blur", onLeave);
    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", release);
      window.removeEventListener("pointercancel", release);
      document.documentElement.removeEventListener("pointerleave", onLeave);
      window.removeEventListener("blur", onLeave);
    };
  }, [still, wake]);

  const blast = useCallback(
    (x: number, y: number) => {
      if (still || !shockwave) return;
      const em = fontPx.current;
      const rand = mulberry32((Math.round(x * 31 + y * 17) ^ field.current.length) >>> 0);
      for (let gi = 0, gs = field.current; gi < gs.length; gi++) {
        const g = gs[gi];
        const dx = g.cx - x;
        const dy = g.cy - y;
        const dist = Math.hypot(dx, dy) || 1;
        const fall = 1 / (1 + (dist / (em * 2.4)) ** 2);
        const speed = em * 16 * fall * live.current.strength * (0.75 + rand() * 0.5);
        g.x.v += (dx / dist) * speed;
        g.y.v += (dy / dist) * speed - em * 4 * fall;
        g.r.v += (rand() - 0.5) * 1400 * fall;
        g.s.v += (rand() - 0.3) * 6 * fall;
      }
      ring.current = { x, y, age: 0 };
      wake();
    },
    [still, shockwave, wake],
  );

  const onPointerDown = useCallback(
    (e: ReactPointerEvent<HTMLDivElement>) => {
      if (still) return;
      const box = boxRef.current;
      if (!box) return;
      const rect = box.getBoundingClientRect();
      const scale = box.offsetWidth > 0 ? rect.width / box.offsetWidth : 1;
      const x = (e.clientX - rect.left) / scale;
      const y = (e.clientY - rect.top) / scale;
      if (e.pointerType === "touch") {
        ptr.current.touch = true;
        ptr.current.x = x;
        ptr.current.y = y;
        ptr.current.active = true;
        wake();
      } else {
        blast(x, y);
      }
    },
    [still, blast, wake],
  );

  const onKeyDown = useCallback(
    (e: KeyboardEvent<HTMLDivElement>) => {
      if (e.key !== "Enter" && e.key !== " ") return;
      e.preventDefault();
      const box = boxRef.current;
      if (!box) return;
      blast(box.offsetWidth / 2, box.offsetHeight / 2);
    },
    [blast],
  );

  const onFocus = useCallback(
    (e: FocusEvent<HTMLDivElement>) => {
      if (still) return;
      if (!e.currentTarget.matches(":focus-visible")) return;
      const now = clock.current;
      field.current.forEach((g, i) => {
        g.kickAt = now + 0.05 + i * 0.045;
      });
      wake();
    },
    [still, wake],
  );

  const fitCqi = 100 / (longest * Math.max(0.35, 0.6 + tracking));
  let letterIndex = 0;

  return (
    <div
      ref={rootRef}
      role={shockwave && !still ? "button" : undefined}
      tabIndex={shockwave && !still ? 0 : undefined}
      aria-label={shockwave && !still ? ariaLabel ?? text : undefined}
      className={cn(
        "relative block w-full select-none rounded-[14px] outline-none focus-visible:ring-2 focus-visible:ring-[#ec5c13]/70 focus-visible:ring-offset-4 focus-visible:ring-offset-transparent",
        !still && shockwave && "cursor-pointer",
        className,
      )}
      style={{ containerType: "inline-size", touchAction: "pan-y", WebkitTapHighlightColor: "transparent" }}
      onPointerDown={onPointerDown}
      onKeyDown={onKeyDown}
      onFocus={onFocus}
    >
      <div
        ref={boxRef}
        aria-hidden="true"
        className="relative"
        style={{
          fontFamily,
          fontWeight,
          fontSize: `min(${fontSize}px, ${fitCqi.toFixed(3)}cqi)`,
          letterSpacing: `${tracking}em`,
          lineHeight: 1.04,
          textAlign: align,
          color: ink,
          paddingBlock: "0.12em",
        }}
      >
        {words.map((w, wi) =>
          /^\s+$/.test(w) ? (
            <span key={`s${wi}`}>{" "}</span>
          ) : (
            <span key={`w${wi}`} className="inline-block whitespace-nowrap">
              {Array.from(w).map((ch) => {
                const i = letterIndex++;
                return (
                  <span key={i} data-letter="" className="inline-block will-change-transform" style={{ transformOrigin: "50% 60%" }}>
                    {ch}
                  </span>
                );
              })}
            </span>
          ),
        )}
        <svg
          ref={ringRef}
          className="pointer-events-none absolute left-0 top-0 overflow-visible"
          width={100}
          height={100}
          viewBox="0 0 100 100"
          style={{ opacity: 0, transformOrigin: "50% 50%" }}
        >
          <circle cx={50} cy={50} r={49} fill="none" stroke={accent} strokeWidth={1.25} vectorEffect="non-scaling-stroke" />
        </svg>
      </div>
      <span className="sr-only">{ariaLabel ?? text}</span>
    </div>
  );
}

export default MagneticLetters;

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export type BjorkTone = "dark" | "light";

// Canvas, WebGL and SVG attribute colours. DOM code uses the CSS tokens with these as fallbacks.
export const BJORK_PALETTE = {
  dark: {
    bg: "#050505", stage: "#111111", surface: "#121212", raised: "#161616", active: "#202020",
    border: "#232323", borderStrong: "#343434",
    text: "#ededed", textMedium: "rgba(237,237,237,0.72)", textMuted: "rgba(237,237,237,0.52)",
    textSoft: "rgba(237,237,237,0.36)", textFaint: "rgba(237,237,237,0.22)", hair: "rgba(237,237,237,0.12)",
    accent: "#ec5c13", accentInk: "#ec5c13", accentFill: "#b84a12", accentSoft: "rgba(236,92,19,0.12)", accentMuted: "rgba(236,92,19,0.24)",
    accentFg: "#fff2ea", success: "#4cc38a", warning: "#f2b544", error: "#ff5c4d",
  },
  light: {
    bg: "#f7f5ef", stage: "#f7f5ef", surface: "#fffcf6", raised: "#f5efe3", active: "#efe7d8",
    border: "#eee6db", borderStrong: "#e1d7c8",
    text: "#171717", textMedium: "rgba(23,23,23,0.72)", textMuted: "rgba(23,23,23,0.52)",
    textSoft: "rgba(23,23,23,0.36)", textFaint: "rgba(23,23,23,0.22)", hair: "rgba(23,23,23,0.10)",
    accent: "#ec7d43", accentInk: "#b4531f", accentFill: "#ec7d43", accentSoft: "rgba(236,125,67,0.10)", accentMuted: "rgba(236,125,67,0.20)",
    accentFg: "#3f2112", success: "#1f8a55", warning: "#a86b00", error: "#c8361f",
  },
} as const;

"use client";

import { useSyncExternalStore } from "react";
import { useTheme } from "next-themes";
import type { BjorkTone } from "./palette";

const subscribeNoop = () => () => {};
const getMounted = () => true;
const getServerMounted = () => false;

/**
 * Resolves the tone for a component. An explicit `tone` always wins.
 * Otherwise it follows next-themes' resolved theme, but only after mount,
 * so the server render and first client render agree on dark.
 */
export function useBjorkTone(tone?: BjorkTone): BjorkTone {
  const { resolvedTheme } = useTheme();
  const mounted = useSyncExternalStore(subscribeNoop, getMounted, getServerMounted);
  if (tone) return tone;
  if (!mounted) return "dark";
  return resolvedTheme === "light" ? "light" : "dark";
}

"use client";

import { useCallback, useEffect, useMemo, useRef, type RefObject } from "react";

export interface VisibleLoopOptions {
  enabled?: boolean;
  fpsCap?: number;
  rootMargin?: string;
}

/**
 * Runs `frame(dt, t)` on requestAnimationFrame while the element is near the viewport,
 * the tab is visible and `enabled` is not false. Return `false` from `frame` to go idle
 * until `wake()` is called. Writes `data-loop` on the element: running, idle or paused.
 */
export function useVisibleLoop(
  ref: RefObject<HTMLElement | null>,
  frame: (dt: number, t: number) => boolean | void,
  opts?: VisibleLoopOptions,
): { wake: () => void } {
  const enabled = opts?.enabled !== false;
  const fpsCap = opts?.fpsCap ?? 0;
  const rootMargin = opts?.rootMargin ?? "96px";

  const frameRef = useRef(frame);
  useEffect(() => {
    frameRef.current = frame;
  }, [frame]);

  const wakeRef = useRef<() => void>(() => {});
  const wake = useCallback(() => wakeRef.current(), []);

  useEffect(() => {
    const el = ref.current;
    if (!el || typeof window === "undefined") return;

    let wants = true; // false once the frame callback returns false
    let inView = false;
    let raf = 0;
    let last = 0;
    let t = 0;
    const minFrame = fpsCap > 0 ? 1000 / fpsCap : 0;

    const canRun = () => enabled && inView && document.visibilityState === "visible";
    const stop = () => {
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
    };

    const update = () => {
      if (!enabled) {
        stop();
        el.dataset.loop = "paused";
        return;
      }
      if (!wants) {
        stop();
        el.dataset.loop = "idle";
        return;
      }
      if (!canRun()) {
        stop();
        el.dataset.loop = "paused";
        return;
      }
      el.dataset.loop = "running";
      if (!raf) {
        last = performance.now();
        raf = requestAnimationFrame(tick);
      }
    };

    const tick = (now: number) => {
      raf = 0;
      if (!canRun() || !wants) {
        update();
        return;
      }
      const elapsed = now - last;
      if (minFrame && elapsed < minFrame - 0.5) {
        raf = requestAnimationFrame(tick);
        return;
      }
      last = now;
      const dt = Math.min(0.05, Math.max(0, elapsed / 1000));
      t += dt;
      const keep = frameRef.current(dt, t);
      if (keep === false) {
        wants = false;
        update();
        return;
      }
      raf = requestAnimationFrame(tick);
    };

    const observer = new IntersectionObserver(
      ([entry]) => {
        inView = entry.isIntersecting;
        update();
      },
      { rootMargin },
    );
    observer.observe(el);

    const onVisibility = () => update();
    document.addEventListener("visibilitychange", onVisibility);

    wakeRef.current = () => {
      wants = true;
      update();
    };

    update();

    return () => {
      stop();
      observer.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      wakeRef.current = () => {};
    };
  }, [ref, enabled, fpsCap, rootMargin]);

  return useMemo(() => ({ wake }), [wake]);
}

// matchMedia based check. False on the server.
export function isCoarsePointer(): boolean {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return false;
  return window.matchMedia("(pointer: coarse)").matches;
}

// Seeded randomness and noise. Deterministic for a given seed, so previews and tests repeat.

// Small fast PRNG. Returns floats in [0, 1).
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// FNV-1a 32-bit.
export function hashString(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

// Integer lattice hash to [-1, 1].
function latticeHash(seed: number, x: number, y = 0): number {
  let h = Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263) ^ Math.imul(seed | 0, 2246822519);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return ((h >>> 0) / 4294967295) * 2 - 1;
}

function smooth(t: number): number {
  return t * t * (3 - 2 * t);
}

export function valueNoise1D(seed: number): (x: number) => number {
  return (x: number) => {
    const i = Math.floor(x);
    const f = x - i;
    const a = latticeHash(seed, i);
    const b = latticeHash(seed, i + 1);
    return a + (b - a) * smooth(f);
  };
}

export function fbm1D(seed: number, octaves = 3): (x: number) => number {
  const layers = Array.from({ length: octaves }, (_, o) => valueNoise1D(seed + o * 101));
  let norm = 0;
  for (let o = 0; o < octaves; o++) norm += 0.5 ** o;
  return (x: number) => {
    let sum = 0;
    let amp = 1;
    let freq = 1;
    for (let o = 0; o < octaves; o++) {
      sum += amp * layers[o](x * freq);
      amp *= 0.5;
      freq *= 2;
    }
    return sum / norm;
  };
}

export function valueNoise2D(seed: number): (x: number, y: number) => number {
  return (x: number, y: number) => {
    const xi = Math.floor(x);
    const yi = Math.floor(y);
    const fx = smooth(x - xi);
    const fy = smooth(y - yi);
    const a = latticeHash(seed, xi, yi);
    const b = latticeHash(seed, xi + 1, yi);
    const c = latticeHash(seed, xi, yi + 1);
    const d = latticeHash(seed, xi + 1, yi + 1);
    const top = a + (b - a) * fx;
    const bottom = c + (d - c) * fx;
    return top + (bottom - top) * fy;
  };
}

// Pure spring math, no React. Units: stiffness k, damping d (coefficient), mass m, time in seconds.

export interface SpringConfig {
  stiffness: number;
  damping: number;
  mass: number;
}

export interface SpringState {
  x: number;
  v: number;
}

// Damping ratio zeta = d / (2 * sqrt(k * m)).
export function dampingRatio(c: SpringConfig): number {
  return c.damping / (2 * Math.sqrt(c.stiffness * c.mass));
}

// Exact solution of y'' = -(k/m) y - (d/m) y' for displacement y0 and velocity v0 at time t.
// Returns displacement and velocity together so stepping can be exact, not integrated.
function solveLinear(t: number, c: SpringConfig, y0: number, v0: number): { y: number; v: number } {
  const w0 = Math.sqrt(c.stiffness / c.mass);
  const z = dampingRatio(c);

  if (Math.abs(z - 1) < 1e-9) {
    // Critically damped.
    const e = Math.exp(-w0 * t);
    const b = v0 + w0 * y0;
    return { y: e * (y0 + b * t), v: e * (b - w0 * (y0 + b * t)) };
  }
  if (z < 1) {
    // Underdamped.
    const wd = w0 * Math.sqrt(1 - z * z);
    const a = z * w0;
    const B = (v0 + a * y0) / wd;
    const e = Math.exp(-a * t);
    const cos = Math.cos(wd * t);
    const sin = Math.sin(wd * t);
    return {
      y: e * (y0 * cos + B * sin),
      v: e * (-a * (y0 * cos + B * sin) + wd * (-y0 * sin + B * cos)),
    };
  }
  // Overdamped.
  const s = w0 * Math.sqrt(z * z - 1);
  const r1 = -z * w0 + s;
  const r2 = -z * w0 - s;
  const B = (v0 - r1 * y0) / (r2 - r1);
  const A = y0 - B;
  const e1 = Math.exp(r1 * t);
  const e2 = Math.exp(r2 * t);
  return { y: A * e1 + B * e2, v: A * r1 * e1 + B * r2 * e2 };
}

// Analytic position at time t for a spring from `from` to `to` with initial velocity v0.
export function springAt(t: number, c: SpringConfig, from = 0, to = 1, v0 = 0): number {
  return to + solveLinear(t, c, from - to, v0).y;
}

// Overshoot as a fraction of the total travel. Zero when critically or overdamped.
export function overshoot(c: SpringConfig): number {
  const z = dampingRatio(c);
  if (z >= 1) return 0;
  return Math.exp((-Math.PI * z) / Math.sqrt(1 - z * z));
}

// Seconds until the spring stays within epsilon of its target (fraction of travel).
// Found by scanning backwards from a bound derived from the slowest decay rate.
export function settleTime(c: SpringConfig, epsilon = 0.001): number {
  const w0 = Math.sqrt(c.stiffness / c.mass);
  const z = dampingRatio(c);
  const slowest = z < 1 ? z * w0 : (z - Math.sqrt(z * z - 1)) * w0;
  const tEnd = (Math.log(1 / epsilon) / slowest) * 1.5 + 0.05;
  const steps = 4000;
  const dt = tEnd / steps;
  const band = epsilon;
  let last = 0;
  for (let i = 0; i <= steps; i++) {
    const t = i * dt;
    if (Math.abs(springAt(t, c, 1, 0, 0)) >= band) last = t;
  }
  return last + dt;
}

// Advances the state by dt towards `target`. Uses the exact solution of the linear spring
// (no integration), so it tracks springAt to rounding error at any step size and stays stable
// for stiff configs where a fixed-step integrator drifts.
export function stepSpring(s: SpringState, target: number, c: SpringConfig, dt: number): void {
  if (dt <= 0) return;
  const r = solveLinear(dt, c, s.x - target, s.v);
  s.x = target + r.y;
  s.v = r.v;
}
